/**
 * AgentGrid component.
 *
 * Renders a CSS Grid of agent log panels. Each cell shows an AgentLog
 * with a header containing the agent's profile name and an active/inactive
 * status dot. When there are no agents a centered empty-state message is
 * displayed.
 */

import './AgentGrid.css';
import type { DevelopAgentInfo } from './types';
import { AgentLog } from './AgentLog';

interface AgentGridProps {
  agents: DevelopAgentInfo[];
}

export function AgentGrid({ agents }: AgentGridProps) {
  if (agents.length === 0) {
    return (
      <div className="agent-grid-empty">
        No active agents
      </div>
    );
  }

  return (
    <div className="agent-grid">
      {agents.map((agent) => (
        <div key={agent.agentId} className="agent-cell">
          <div className="agent-cell-header">
            <span className="agent-cell-header-name">
              <span
                className={`agent-cell-status-dot agent-cell-status-dot--${agent.active ? 'active' : 'inactive'}`}
              />
              {agent.profile}
            </span>
          </div>
          <div className="agent-cell-body">
            <AgentLog entries={agent.log} />
          </div>
        </div>
      ))}
    </div>
  );
}

.agent-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(var(--engin-agent-min-width), 1fr));
  grid-template-rows: 1fr;
  flex: 1;
  overflow: hidden;
  gap: 1px;
  background: var(--engin-border);
}

.agent-grid-empty {
  display: flex;
  align-items: center;
  justify-content: center;
  flex: 1;
  color: var(--engin-text-muted);
  font-size: 14px;
}

.agent-cell {
  display: flex;
  flex-direction: column;
  background: var(--engin-bg-primary);
  overflow: hidden;
  min-height: 0;
}

.agent-cell-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--engin-space-xs) var(--engin-space-sm);
  background: var(--engin-bg-surface);
  font-size: 12px;
  flex-shrink: 0;
}

.agent-cell-header-name {
  display: flex;
  align-items: center;
  gap: 6px;
}

.agent-cell-status-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex-shrink: 0;
}

.agent-cell-status-dot--active {
  background: var(--engin-success);
}

.agent-cell-status-dot--inactive {
  background: var(--engin-text-muted);
  opacity: 0.4;
}

.agent-cell-body {
  flex: 1;
  overflow: hidden;
  min-height: 0;
}

